cd <repo>/daemon && d=$(mktemp -d) && cat > $d/stress.py <<'EOF'
import sys, random, multiprocessing as mp
sys.path.insert(0, sys.argv[1])
from chats import ChatStore
root = sys.argv[2]
def worker(n):
    s = ChatStore(root); random.seed(n); ids = []
    for i in range(60):
        r = random.random()
        cur = s.list()
        pick = random.choice(cur)["id"] if cur else None
        if r < 0.5:
            ids.append(s.record(chat_id=pick if random.random()<0.6 else None, agent_id=str(n%3), agent_label="a",
                     backend="claude", session_id="x", project_dir="", exchange={"transcript": f"hi {i}"}))
        elif r < 0.65 and pick: s.rename(pick, f"t{i}")
        elif r < 0.8 and pick: s.pin(pick, random.random()<0.5)
        elif r < 0.9 and pick: s.delete(pick)
        else: s.prune("last100"); s.set_current(str(n%3), pick)
if __name__ == "__main__":
    with mp.Pool(8) as p: p.map(worker, range(8))
    s = ChatStore(root); ids = [c["id"] for c in s.list()]
    import pathlib
    files = {p.stem for p in pathlib.Path(root).glob("*.json") if p.name != "index.json"}
    print("entries", len(ids), "unique", len(set(ids)), "files", len(files), "match", set(ids)==files)
EOF
python3 -I $d/stress.py "$PWD" $d/chats; rm -rf $d

